using System;
using SkillEditor.Data;

namespace SkillEditor.Runtime
{
    /// <summary>
    /// 技能系统组件 - GAS的核心实现
    /// 管理技能、效果、属性、标签的中枢组件
    /// </summary>
    public class AbilitySystemComponent
    {
        /// <summary>
        /// 唯一标识符
        /// </summary>
        public string Id { get; private set; }

        /// <summary>
        /// 属性容器
        /// </summary>
        public AttributeSetContainer Attributes { get; private set; }

        /// <summary>
        /// 标签容器
        /// </summary>
        public GameplayTagContainer OwnedTags { get; private set; }

        /// <summary>
        /// 技能容器
        /// </summary>
        public AbilityContainer Abilities { get; private set; }

        /// <summary>
        /// 效果容器（别名，方便访问）
        /// </summary>
        public GameplayEffectContainer EffectContainer{ get; private set; }

        /// <summary>
        /// 所属的GameObject
        /// </summary>
        public UnityEngine.GameObject Owner { get; private set; }

        /// <summary>
        /// 是否已初始化
        /// </summary>
        public bool IsInitialized { get; private set; }

        // ============ 事件 ============

        public event Action<GameplayAbilitySpec> OnAbilityActivated;
        public event Action<GameplayAbilitySpec, bool> OnAbilityEnded;
        public event Action<GameplayEffectSpec, AbilitySystemComponent> OnEffectApplied;
        public event Action<GameplayEffectSpec> OnEffectRemoved;
        public event Action<GameplayTag, bool> OnTagChanged;

        public event Action<GameplayEventType> OnTGameplayEvent;
        // ============ 构造函数 ============

        public AbilitySystemComponent(UnityEngine.GameObject owner = null)
        {
            Id = Guid.NewGuid().ToString();
            Owner = owner;

            // 初始化容器
            Attributes = new AttributeSetContainer();
            OwnedTags = new GameplayTagContainer();
            Abilities = new AbilityContainer(this);
            EffectContainer = new GameplayEffectContainer(this);

            // 订阅事件
            SubscribeEvents();

            IsInitialized = true;

            // 注册到GASHost
            GASHost.Instance.Register(this);
        }

        /// <summary>
        /// 订阅内部事件
        /// </summary>
        private void SubscribeEvents()
        {
            // 标签变化事件
            OwnedTags.OnTagsChanged += () =>
            {
                // 可以在这里处理标签变化的全局逻辑
            };

            Attributes.OnAnyAttributeChanged += (Attribute, before, after) =>
            {
                if (Attribute.AttrType == AttrType.Health)
                {
                    if (after < before)
                    {
                        OnTGameplayEvent?.Invoke(GameplayEventType.OnTakeDamage);
                    }
                }
            };
        }

        // ============ 技能相关 ============

        /// <summary>
        /// 授予技能
        /// </summary>
        public GameplayAbilitySpec GrantAbility(SkillGraphData abilityData)
        {
            if (abilityData == null)
                return null;

            return Abilities.GrantAbility(abilityData);
        }

        /// <summary>
        /// 授予技能并设置技能ID
        /// </summary>
        public GameplayAbilitySpec GrantAbility(SkillGraphData abilityData, int skillId)
        {
            if (abilityData == null)
                return null;

            return Abilities.GrantAbility(abilityData, skillId);
        }

        /// <summary>
        /// 移除技能
        /// </summary>
        public bool RemoveAbility(GameplayAbilitySpec spec)
        {
            return Abilities.RemoveAbility(spec);
        }

        /// <summary>
        /// 尝试激活技能
        /// </summary>
        public bool TryActivateAbility(GameplayAbilitySpec spec, AbilitySystemComponent target = null)
        {
            if (spec == null)
                return false;

            bool success = Abilities.TryActivateAbility(spec, target);

            if (success)
            {
                OnAbilityActivated?.Invoke(spec);

                // 订阅技能结束事件
                spec.OnEnded += HandleAbilityEnded;
            }

            return success;
        }

        /// <summary>
        /// 取消技能
        /// </summary>
        public void CancelAbility(GameplayAbilitySpec spec)
        {
            Abilities.CancelAbility(spec);
        }

        /// <summary>
        /// 结束技能
        /// </summary>
        public void EndAbility(GameplayAbilitySpec spec, bool wasCancelled = false)
        {
            Abilities.EndAbility(spec, wasCancelled);
        }

        /// <summary>
        /// 处理技能结束
        /// </summary>
        private void HandleAbilityEnded(GameplayAbilitySpec spec, bool wasCancelled)
        {
            spec.OnEnded -= HandleAbilityEnded;
            OnAbilityEnded?.Invoke(spec, wasCancelled);
        }

        // ============ 效果相关 ============

        /// <summary>
        /// 移除效果
        /// </summary>
        public bool RemoveActiveEffect(GameplayEffectSpec effectSpec)
        {
            return EffectContainer.RemoveEffect(effectSpec);
        }

        /// <summary>
        /// 移除带有指定标签的所有效果
        /// </summary>
        public int RemoveActiveEffectsWithTags(GameplayTagSet tags)
        {
            return EffectContainer.RemoveEffectsWithTags(tags);
        }

        // ============ 标签相关 ============

        /// <summary>
        /// 检查是否拥有标签
        /// </summary>
        public bool HasTag(GameplayTag tag)
        {
            return OwnedTags.HasTag(tag);
        }

        /// <summary>
        /// 检查是否拥有所有标签
        /// </summary>
        public bool HasAllTags(GameplayTagSet tags)
        {
            return OwnedTags.HasAllTags(tags);
        }

        /// <summary>
        /// 检查是否拥有任意标签
        /// </summary>
        public bool HasAnyTags(GameplayTagSet tags)
        {
            return OwnedTags.HasAnyTags(tags);
        }

        /// <summary>
        /// 检查是否不拥有任何指定标签
        /// </summary>
        public bool HasNoneTags(GameplayTagSet tags)
        {
            return OwnedTags.HasNoneTags(tags);
        }

        // ============ 更新 ============

        /// <summary>
        /// 每帧更新
        /// </summary>
        public void Tick(float deltaTime)
        {
            // 更新技能
            Abilities.Tick(deltaTime);

            // 更新效果
            EffectContainer.Tick(deltaTime);
        }

        // ============ 清理 ============

        /// <summary>
        /// 销毁ASC
        /// </summary>
        public void Destroy()
        {
            // 从GASHost注销
            GASHost.Instance.Unregister(this);

            // 清理所有技能和效果
            Abilities.Clear();
            EffectContainer.Clear();
            OwnedTags.Clear();

            IsInitialized = false;
        }

    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace SkillEditor.Data
{
    /// <summary>
    /// 游戏属性 - 对应虚幻引擎的 FGameplayAttributeData
    /// 包含 BaseValue（永久值）和 CurrentValue（计算后的值）
    /// 内嵌 Aggregator 用于管理修改器
    /// </summary>
    [Serializable]
    public class Attribute
    {
        /// <summary>
        /// 属性类型
        /// </summary>
        [SerializeField]
        private AttrType attrType;
        public AttrType AttrType => attrType;

        /// <summary>
        /// 基础值 - 永久值，只被 Instant 效果修改
        /// </summary>
        [SerializeField]
        private float baseValue;
        public float BaseValue
        {
            get => baseValue;
            set
            {
                float oldValue = baseValue;
                float newValue = value;

                // 触发修改前回调
                OnPreBaseValueChange?.Invoke(this, ref newValue);

                // 应用限制
                if (hasMinValue) newValue = Mathf.Max(newValue, minValue);
                if (hasMaxValue) newValue = Mathf.Min(newValue, maxValue);

                baseValue = newValue;

                // BaseValue 变化后需要重新计算 CurrentValue
                MarkDirty();
                Recalculate();

                // 触发修改后回调
                OnPostBaseValueChange?.Invoke(this, oldValue, newValue);
            }
        }

        /// <summary>
        /// 当前值 - BaseValue + 所有活跃 Modifier 的结果
        /// </summary>
        [SerializeField]
        private float currentValue;
        public float CurrentValue
        {
            get => currentValue;
            set
            {
                float oldValue = currentValue;
                float newValue = value;

                // 触发修改前回调
                OnPreCurrentValueChange?.Invoke(this, ref newValue);

                // 应用限制
                if (hasMinValue) newValue = Mathf.Max(newValue, minValue);
                if (hasMaxValue) newValue = Mathf.Min(newValue, maxValue);

                currentValue = newValue;

                // 触发修改后回调
                OnPostCurrentValueChange?.Invoke(this, oldValue, newValue);
            }
        }

        /// <summary>
        /// 是否为 Meta 属性（临时占位符，如伤害值）
        /// </summary>
        [SerializeField]
        private bool isMeta;
        public bool IsMeta => isMeta;

        /// <summary>
        /// 是否有最小值限制
        /// </summary>
        [SerializeField]
        private bool hasMinValue;
        public bool HasMinValue => hasMinValue;

        /// <summary>
        /// 最小值
        /// </summary>
        [SerializeField]
        private float minValue;
        public float MinValue => minValue;

        /// <summary>
        /// 是否有最大值限制
        /// </summary>
        [SerializeField]
        private bool hasMaxValue;
        public bool HasMaxValue => hasMaxValue;

        /// <summary>
        /// 最大值
        /// </summary>
        [SerializeField]
        private float maxValue;
        public float MaxValue => maxValue;

        // ============ 内嵌 Aggregator ============

        /// <summary>
        /// 活跃的修改器列表
        /// </summary>
        [NonSerialized]
        private List<ActiveModifier> activeModifiers;

        /// <summary>
        /// 聚合模式
        /// </summary>
        [NonSerialized]
        private AggregatorMode aggregatorMode = AggregatorMode.Default;
        public AggregatorMode AggregatorMode
        {
            get => aggregatorMode;
            set => aggregatorMode = value;
        }

        /// <summary>
        /// 是否需要重新计算
        /// </summary>
        [NonSerialized]
        private bool isDirty = false;

        /// <summary>
        /// 活跃修改器数量
        /// </summary>
        public int ModifierCount => activeModifiers?.Count ?? 0;

        // ============ 事件回调 ============

        /// <summary>
        /// BaseValue 修改前回调 - 可用于 Clamp
        /// </summary>
        public delegate void PreValueChangeDelegate(Attribute attribute, ref float newValue);
        public event PreValueChangeDelegate OnPreBaseValueChange;
        public event PreValueChangeDelegate OnPreCurrentValueChange;

        /// <summary>
        /// 值修改后回调 - 用于 UI 更新等
        /// </summary>
        public delegate void PostValueChangeDelegate(Attribute attribute, float oldValue, float newValue);
        public event PostValueChangeDelegate OnPostBaseValueChange;
        public event PostValueChangeDelegate OnPostCurrentValueChange;

        // ============ 构造函数 ============

        public Attribute()
        {
            activeModifiers = new List<ActiveModifier>();
        }

        public Attribute(AttrType attrType, float defaultValue = 0f)
        {
            this.attrType = attrType;
            this.baseValue = defaultValue;
            this.currentValue = defaultValue;
            this.activeModifiers = new List<ActiveModifier>();
        }

        // ============ 基础方法 ============

        /// <summary>
        /// 初始化属性值（同时设置 BaseValue 和 CurrentValue）
        /// </summary>
        public void Initialize(float value)
        {
            baseValue = value;
            currentValue = value;
        }

        /// <summary>
        /// 设置值限制
        /// </summary>
        public void SetClamp(float? min, float? max)
        {
            hasMinValue = min.HasValue;
            if (min.HasValue) minValue = min.Value;

            hasMaxValue = max.HasValue;
            if (max.HasValue) maxValue = max.Value;
        }

        /// <summary>
        /// 设置为 Meta 属性
        /// </summary>
        public void SetAsMeta(bool isMeta = true)
        {
            this.isMeta = isMeta;
        }

        /// <summary>
        /// 重置当前值为基础值
        /// </summary>
        public void ResetCurrentToBase()
        {
            CurrentValue = BaseValue;
        }

        /// <summary>
        /// 清除所有事件监听
        /// </summary>
        public void ClearCallbacks()
        {
            OnPreBaseValueChange = null;
            OnPreCurrentValueChange = null;
            OnPostBaseValueChange = null;
            OnPostCurrentValueChange = null;
        }

        // ============ Aggregator 方法 ============

        /// <summary>
        /// 添加修改器
        /// </summary>
        public void AddModifier(AttributeModifier modifier, object source = null)
        {
            if (activeModifiers == null)
                activeModifiers = new List<ActiveModifier>();

            var activeModifier = new ActiveModifier
            {
                Modifier = modifier,
                Source = source,
                AppliedTime = Time.time
            };

            activeModifiers.Add(activeModifier);
            MarkDirty();
        }

        /// <summary>
        /// 移除修改器
        /// </summary>
        public bool RemoveModifier(AttributeModifier modifier)
        {
            if (activeModifiers == null) return false;

            int removed = activeModifiers.RemoveAll(m => m.Modifier == modifier);
            if (removed > 0)
            {
                MarkDirty();
                return true;
            }
            return false;
        }

        /// <summary>
        /// 移除来自指定源的所有修改器
        /// </summary>
        public int RemoveModifiersFromSource(object source)
        {
            if (activeModifiers == null) return 0;

            int removed = activeModifiers.RemoveAll(m => m.Source == source);
            if (removed > 0)
            {
                MarkDirty();
            }
            return removed;
        }

        /// <summary>
        /// 清除所有修改器
        /// </summary>
        public void ClearModifiers()
        {
            activeModifiers?.Clear();
            MarkDirty();
        }

        /// <summary>
        /// 标记为需要重新计算
        /// </summary>
        public void MarkDirty()
        {
            isDirty = true;
        }

        /// <summary>
        /// 重新计算 CurrentValue
        /// </summary>
        public void Recalculate(ModifierCalculationContext context = null)
        {
            if (!isDirty) return;

            float newValue = CalculateNewValue(context);
            CurrentValue = newValue;
            isDirty = false;
        }

        /// <summary>
        /// 计算新值
        /// </summary>
        private float CalculateNewValue(ModifierCalculationContext context)
        {
            if (activeModifiers == null || activeModifiers.Count == 0)
                return baseValue;

            // 根据聚合模式筛选修改器
            var filteredModifiers = FilterModifiers(activeModifiers);

            // 分组计算：先加法，再乘法，最后覆盖
            float additive = 0f;
            float multiplicative = 1f;
            float? overrideValue = null;

            foreach (var activeModifier in filteredModifiers)
            {
                var modifier = activeModifier.Modifier;
                float magnitude = modifier.CalculateMagnitude(context);

                // 从来源获取堆叠层数（通过反射获取 StackCount 属性）
                int stackCount = 1;
                var source = activeModifier.Source;
                if (source != null)
                {
                    var stackCountProp = source.GetType().GetProperty("StackCount");
                    if (stackCountProp != null)
                    {
                        stackCount = (int)stackCountProp.GetValue(source);
                    }
                }

                switch (modifier.Operation)
                {
                    case ModifierOperation.Add:
                        // 加法：直接乘以层数（10伤害 × 3层 = 30伤害）
                        additive += magnitude * stackCount;
                        break;
                    case ModifierOperation.Multiply:
                        // 乘法：转换为百分比累加（1.1 表示 +10%，3层 = +30% = 1.3）
                        // 公式：1 + (magnitude - 1) * stackCount
                        float percentBonus = (magnitude - 1f) * stackCount;
                        multiplicative *= (1f + percentBonus);
                        break;
                    case ModifierOperation.Divide:
                        // 除法：同样转换为百分比
                        if (Mathf.Abs(magnitude) > 0.0001f)
                        {
                            float divideBonus = (magnitude - 1f) * stackCount;
                            multiplicative /= (1f + divideBonus);
                        }
                        break;
                    case ModifierOperation.Override:
                        overrideValue = magnitude;
                        break;
                }
            }

            // 计算最终值
            // 公式: (BaseValue + Additive) * Multiplicative
            // 如果有 Override，则直接使用 Override 值
            if (overrideValue.HasValue)
            {
                return overrideValue.Value;
            }

            return (baseValue + additive) * multiplicative;
        }

        /// <summary>
        /// 根据聚合模式筛选修改器
        /// </summary>
        private List<ActiveModifier> FilterModifiers(List<ActiveModifier> modifiers)
        {
            switch (aggregatorMode)
            {
                case AggregatorMode.MostNegativeModifier:
                    return FilterMostNegative(modifiers);

                case AggregatorMode.MostPositiveModifier:
                    return FilterMostPositive(modifiers);

                case AggregatorMode.MostNegativeWithAllPositive:
                    return FilterMostNegativeWithAllPositive(modifiers);

                case AggregatorMode.Default:
                default:
                    return modifiers;
            }
        }

        private List<ActiveModifier> FilterMostNegative(List<ActiveModifier> modifiers)
        {
            var result = new List<ActiveModifier>();
            ActiveModifier? mostNegative = null;
            float mostNegativeValue = 0f;

            foreach (var mod in modifiers)
            {
                if (mod.Modifier.Operation == ModifierOperation.Add)
                {
                    float magnitude = mod.Modifier.CalculateMagnitude(null);
                    if (magnitude < 0 && magnitude < mostNegativeValue)
                    {
                        mostNegative = mod;
                        mostNegativeValue = magnitude;
                    }
                }
                else
                {
                    result.Add(mod);
                }
            }

            if (mostNegative.HasValue)
            {
                result.Add(mostNegative.Value);
            }

            return result;
        }

        private List<ActiveModifier> FilterMostPositive(List<ActiveModifier> modifiers)
        {
            var result = new List<ActiveModifier>();
            ActiveModifier? mostPositive = null;
            float mostPositiveValue = 0f;

            foreach (var mod in modifiers)
            {
                if (mod.Modifier.Operation == ModifierOperation.Add)
                {
                    float magnitude = mod.Modifier.CalculateMagnitude(null);
                    if (magnitude > 0 && magnitude > mostPositiveValue)
                    {
                        mostPositive = mod;
                        mostPositiveValue = magnitude;
                    }
                }
                else
                {
                    result.Add(mod);
                }
            }

            if (mostPositive.HasValue)
            {
                result.Add(mostPositive.Value);
            }

            return result;
        }

        private List<ActiveModifier> FilterMostNegativeWithAllPositive(List<ActiveModifier> modifiers)
        {
            var result = new List<ActiveModifier>();
            ActiveModifier? mostNegative = null;
            float mostNegativeValue = 0f;

            foreach (var mod in modifiers)
            {
                if (mod.Modifier.Operation == ModifierOperation.Add)
                {
                    float magnitude = mod.Modifier.CalculateMagnitude(null);
                    if (magnitude >= 0)
                    {
                        result.Add(mod);
                    }
                    else if (magnitude < mostNegativeValue)
                    {
                        mostNegative = mod;
                        mostNegativeValue = magnitude;
                    }
                }
                else
                {
                    result.Add(mod);
                }
            }

            if (mostNegative.HasValue)
            {
                result.Add(mostNegative.Value);
            }

            return result;
        }

        /// <summary>
        /// 获取所有活跃修改器
        /// </summary>
        public IEnumerable<ActiveModifier> GetActiveModifiers()
        {
            return activeModifiers ?? (IEnumerable<ActiveModifier>)Array.Empty<ActiveModifier>();
        }

        public override string ToString()
        {
            return $"{attrType}: Base={BaseValue}, Current={CurrentValue}";
        }
    }

    /// <summary>
    /// 活跃修改器 - 包含修改器和来源信息
    /// </summary>
    public struct ActiveModifier
    {
        /// <summary>
        /// 修改器
        /// </summary>
        public AttributeModifier Modifier;

        /// <summary>
        /// 来源（如 GameplayEffectSpec）
        /// </summary>
        public object Source;

        /// <summary>
        /// 应用时间
        /// </summary>
        public float AppliedTime;
    }

    /// <summary>
    /// 聚合模式 - 对应虚幻引擎的 FAggregatorEvaluateMetaData
    /// </summary>
    public enum AggregatorMode
    {
        /// <summary>
        /// 默认 - 所有修改器都参与计算
        /// </summary>
        Default,

        /// <summary>
        /// 只保留最负的加法修改器
        /// </summary>
        MostNegativeModifier,

        /// <summary>
        /// 只保留最正的加法修改器
        /// </summary>
        MostPositiveModifier,

        /// <summary>
        /// 保留最负的加法修改器和所有正加法修改器
        /// 用于移动速度等场景（Paragon 模式）
        /// </summary>
        MostNegativeWithAllPositive
    }
}

using System;
using UnityEngine;

namespace SkillEditor.Data
{
    /// <summary>
    /// 属性修改器 - 定义如何修改属性
    /// 对应虚幻引擎的 FGameplayModifierInfo
    /// </summary>
    [Serializable]
    public class AttributeModifier
    {
        /// <summary>
        /// 目标属性类型
        /// </summary>
        [SerializeField]
        private AttrType targetAttrType;
        public AttrType TargetAttrType
        {
            get => targetAttrType;
            set => targetAttrType = value;
        }

        /// <summary>
        /// 修改操作类型
        /// </summary>
        [SerializeField]
        private ModifierOperation operation = ModifierOperation.Add;
        public ModifierOperation Operation
        {
            get => operation;
            set => operation = value;
        }

        /// <summary>
        /// 基础数值
        /// </summary>
        [SerializeField]
        private float magnitude;
        public float Magnitude
        {
            get => magnitude;
            set => magnitude = value;
        }

        /// <summary>
        /// 数值公式（支持表达式，如 "Caster.Attack * 1.5"）
        /// 如果设置了公式，则优先使用公式计算
        /// </summary>
        [SerializeField]
        private string magnitudeFormula;
        public string MagnitudeFormula
        {
            get => magnitudeFormula;
            set => magnitudeFormula = value;
        }

        /// <summary>
        /// MMC 计算类型
        /// </summary>
        [SerializeField]
        private MMCType mmcType = MMCType.AttributeBased;
        public MMCType MMCType
        {
            get => mmcType;
            set => mmcType = value;
        }

        /// <summary>
        /// 是否使用 MMC 计算
        /// </summary>
        [SerializeField]
        private bool useMMC = false;
        public bool UseMMC
        {
            get => useMMC;
            set => useMMC = value;
        }

        /// <summary>
        /// 属性捕获类型
        /// </summary>
        [SerializeField]
        private AttributeCaptureType captureType = AttributeCaptureType.Snapshot;
        public AttributeCaptureType CaptureType
        {
            get => captureType;
            set => captureType = value;
        }

        // ============ MMC 详细配置 ============

        /// <summary>
        /// MMC 捕获的属性类型
        /// </summary>
        [SerializeField]
        private AttrType mmcCaptureAttribute = AttrType.Attack;
        public AttrType MMCCaptureAttribute
        {
            get => mmcCaptureAttribute;
            set => mmcCaptureAttribute = value;
        }

        /// <summary>
        /// MMC 属性来源
        /// </summary>
        [SerializeField]
        private MMCAttributeSource mmcAttributeSource = MMCAttributeSource.Source;
        public MMCAttributeSource MMCAttributeSource
        {
            get => mmcAttributeSource;
            set => mmcAttributeSource = value;
        }

        /// <summary>
        /// MMC 系数
        /// </summary>
        [SerializeField]
        private float mmcCoefficient = 1f;
        public float MMCCoefficient
        {
            get => mmcCoefficient;
            set => mmcCoefficient = value;
        }

        /// <summary>
        /// MMC 是否使用快照
        /// </summary>
        [SerializeField]
        private bool mmcUseSnapshot = true;
        public bool MMCUseSnapshot
        {
            get => mmcUseSnapshot;
            set => mmcUseSnapshot = value;
        }

        // ============ 构造函数 ============

        public AttributeModifier() { }

        public AttributeModifier(AttrType targetAttrType, ModifierOperation operation, float magnitude)
        {
            this.targetAttrType = targetAttrType;
            this.operation = operation;
            this.magnitude = magnitude;
        }

        // ============ 方法 ============

        /// <summary>
        /// 计算最终数值
        /// </summary>
        public float CalculateMagnitude(ModifierCalculationContext context)
        {
            // 优先使用 MMC 计算
            if (useMMC)
            {
                return CalculateMMC(context);
            }

            // 其次使用公式
            if (!string.IsNullOrEmpty(magnitudeFormula))
            {
                return EvaluateFormula(context);
            }

            // 最后使用基础数值
            return magnitude;
        }

        /// <summary>
        /// MMC 计算
        /// </summary>
        private float CalculateMMC(ModifierCalculationContext context)
        {
            if (mmcType == MMCType.AttributeBased)
            {
                // 基于属性的 MMC
                float? attrValue = null;

                if (mmcUseSnapshot && context?.SnapshotValues != null)
                {
                    // 使用快照值
                    attrValue = context.GetSnapshotValue(mmcCaptureAttribute);
                }

                if (!attrValue.HasValue)
                {
                    // 实时获取属性值
                    if (mmcAttributeSource == MMCAttributeSource.Source)
                    {
                        attrValue = context?.GetSourceAttribute(mmcCaptureAttribute);
                    }
                    else
                    {
                        attrValue = context?.GetTargetAttribute(mmcCaptureAttribute);
                    }
                }

                // 属性值 × 系数
                return (attrValue ?? 0f) * mmcCoefficient;
            }
            else if (mmcType == MMCType.LevelBased)
            {
                // 基于等级的 MMC
                int level = context?.EffectLevel ?? 1;
                return magnitude * (1 + level * 0.1f);
            }

            return magnitude;
        }

        /// <summary>
        /// 计算公式（简化实现，实际项目中可使用表达式解析器）
        /// </summary>
        private float EvaluateFormula(ModifierCalculationContext context)
        {
            // 简化实现：直接返回基础数值
            // 实际项目中应该实现完整的表达式解析
            // 例如解析 "Caster.Attack * 1.5 + 10"
            if (context == null) return magnitude;

            // TODO: 实现完整的公式解析
            // 这里可以集成第三方表达式解析库，如 NCalc
            return magnitude;
        }

        /// <summary>
        /// 从 AttributeModifierData 创建
        /// </summary>
        public static AttributeModifier FromData(AttributeModifierData data)
        {
            var modifier = new AttributeModifier
            {
                targetAttrType = data.attrType,
                operation = data.operation,
            };

            switch (data.magnitudeSourceType)
            {
                case ModifierMagnitudeSourceType.FixedValue:
                    modifier.magnitude = data.fixedValue;
                    break;
                case ModifierMagnitudeSourceType.Formula:
                    modifier.magnitudeFormula = data.formula;
                    break;
                case ModifierMagnitudeSourceType.ModifierMagnitudeCalculation:
                    modifier.useMMC = true;
                    modifier.mmcType = data.mmcType;
                    // 复制 MMC 详细配置
                    modifier.mmcCaptureAttribute = data.mmcCaptureAttribute;
                    modifier.mmcAttributeSource = data.mmcAttributeSource;
                    modifier.mmcCoefficient = data.mmcCoefficient;
                    modifier.mmcUseSnapshot = data.mmcUseSnapshot;
                    break;
                case ModifierMagnitudeSourceType.SetByCaller:
                    // SetByCaller 需要在运行时从上下文获取
                    break;
            }

            return modifier;
        }

        /// <summary>
        /// 转换为 AttributeModifierData
        /// </summary>
        public AttributeModifierData ToData()
        {
            var data = new AttributeModifierData
            {
                attrType = targetAttrType,
                operation = operation,
            };

            if (useMMC)
            {
                data.magnitudeSourceType = ModifierMagnitudeSourceType.ModifierMagnitudeCalculation;
                data.mmcType = mmcType;
            }
            else if (!string.IsNullOrEmpty(magnitudeFormula))
            {
                data.magnitudeSourceType = ModifierMagnitudeSourceType.Formula;
                data.formula = magnitudeFormula;
            }
            else
            {
                data.magnitudeSourceType = ModifierMagnitudeSourceType.FixedValue;
                data.fixedValue = magnitude;
            }

            return data;
        }

        public override string ToString()
        {
            string opStr = operation switch
            {
                ModifierOperation.Add => "+",
                ModifierOperation.Multiply => "*",
                ModifierOperation.Divide => "/",
                ModifierOperation.Override => "=",
                _ => "?"
            };

            string valueStr = !string.IsNullOrEmpty(magnitudeFormula) ? magnitudeFormula : magnitude.ToString();
            return $"{targetAttrType} {opStr} {valueStr}";
        }
    }

    /// <summary>
    /// 属性捕获类型 - 决定何时捕获属性值
    /// </summary>
    public enum AttributeCaptureType
    {
        /// <summary>
        /// 快照 - 在效果创建时捕获属性值
        /// </summary>
        Snapshot,

        /// <summary>
        /// 追踪 - 实时获取属性值
        /// </summary>
        Track
    }

    /// <summary>
    /// 修改器计算上下文 - 提供计算所需的信息
    /// </summary>
    public class ModifierCalculationContext
    {
        /// <summary>
        /// 效果来源的属性容器
        /// </summary>
        public AttributeSetContainer SourceAttributes { get; set; }

        /// <summary>
        /// 效果目标的属性容器
        /// </summary>
        public AttributeSetContainer TargetAttributes { get; set; }

        /// <summary>
        /// 快照属性值（效果创建时捕获）
        /// </summary>
        public System.Collections.Generic.Dictionary<AttrType, float> SnapshotValues { get; set; }

        /// <summary>
        /// 效果等级
        /// </summary>
        public int EffectLevel { get; set; } = 1;

        /// <summary>
        /// 自定义数据
        /// </summary>
        public System.Collections.Generic.Dictionary<string, object> CustomData { get; set; }

        /// <summary>
        /// 获取来源属性值
        /// </summary>
        public float? GetSourceAttribute(AttrType attrType)
        {
            return SourceAttributes?.GetCurrentValue(attrType);
        }

        /// <summary>
        /// 获取目标属性值
        /// </summary>
        public float? GetTargetAttribute(AttrType attrType)
        {
            return TargetAttributes?.GetCurrentValue(attrType);
        }

        /// <summary>
        /// 获取快照属性值
        /// </summary>
        public float? GetSnapshotValue(AttrType attrType)
        {
            if (SnapshotValues != null && SnapshotValues.TryGetValue(attrType, out float value))
            {
                return value;
            }
            return null;
        }

        /// <summary>
        /// 设置自定义数据
        /// </summary>
        public void SetCustomData(string key, object value)
        {
            CustomData ??= new System.Collections.Generic.Dictionary<string, object>();
            CustomData[key] = value;
        }

        /// <summary>
        /// 获取自定义数据
        /// </summary>
        public T GetCustomData<T>(string key, T defaultValue = default)
        {
            if (CustomData != null && CustomData.TryGetValue(key, out object value) && value is T typedValue)
            {
                return typedValue;
            }
            return defaultValue;
        }
    }
}

using System;
using System.Collections.Generic;
using SkillEditor.Data;
using SkillEditor.Runtime.Utils;

namespace SkillEditor.Runtime
{
    /// <summary>
    /// 效果Spec基类
    /// 瞬时效果: 不授予标签，直接修改BaseValue（永久）
    /// 持续效果: Apply时授予标签+添加Modifier（临时），Remove时移除
    /// </summary>
    public class GameplayEffectSpec
    {
        // ============ 基础标识 ============
        public string SpecId { get; private set; }
        public string SkillId { get; private set; }
        public string NodeGuid { get; private set; }
        public SpecExecutionContext Context { get; private set; }
        public AbilitySystemComponent Source { get; private set; }
        public AbilitySystemComponent Target { get; protected set; }
        public int Level { get; set; } = 1;
        public int StackCount { get; set; } = 1;
        public bool IsRunning { get; protected set; }
        protected bool IsCancelled { get; private set; }

        // ============ 运行时数据（可被修改） ============
        public EffectTagContainer Tags { get; protected set; }
        public float Duration { get; set; }
        public float Period { get; set; }
        public List<AttributeModifier> Modifiers { get; protected set; } = new List<AttributeModifier>();
        public Dictionary<string, float> SetByCallerValues { get; private set; } = new Dictionary<string, float>();
        public Dictionary<AttrType, float> SnapshotValues { get; private set; } = new Dictionary<AttrType, float>();

        // ============ 运行时状态 ============
        public float ActivationTime { get; private set; }
        public bool IsApplied { get; private set; }
        public bool IsExpired { get; private set; }
        public bool WasRefreshed { get; private set; }
        protected float ElapsedTime { get; set; }
        protected float PeriodTimer { get; set; }
        private List<GameplayCueSpec> _triggeredCueSpecs;

        // ============ 静态数据访问 ============
        protected NodeData NodeData => SkillDataCenter.Instance.GetNodeData(SkillId, NodeGuid);
        public EffectNodeData EffectNodeData => NodeData as EffectNodeData;

        public float RemainingTime => EffectNodeData?.durationType == EffectDurationType.Duration ? Math.Max(0f, Duration - ElapsedTime) : -1f;

        // ============ 初始化 ============
        public virtual void Initialize(string skillId, string nodeGuid, SpecExecutionContext context)
        {
            SpecId = Guid.NewGuid().ToString();
            SkillId = skillId;
            NodeGuid = nodeGuid;
            Context = context;
            Source = context?.Caster;
            Level = context?.AbilityLevel ?? 1;
            IsRunning = false;
            IsCancelled = false;
            IsApplied = false;
            IsExpired = false;
            WasRefreshed = false;
            _triggeredCueSpecs = new List<GameplayCueSpec>();

            var effectData = EffectNodeData;
            if (effectData != null)
                Tags = new EffectTagContainer(effectData);

            if (Source?.Attributes != null)
                SnapshotValues = Source.Attributes.CreateSnapshot();

            // 初始化可修改的运行时数据
            Duration = FormulaEvaluator.EvaluateSimple(effectData?.duration, 0f);
            Period = FormulaEvaluator.EvaluateSimple(effectData?.period, 1f);

            if (effectData?.attributeModifiers != null)
            {
                Modifiers.Clear();
                foreach (var modData in effectData.attributeModifiers)
                    Modifiers.Add(AttributeModifier.FromData(modData));
            }

            OnInitialize();
        }

        protected virtual void OnInitialize()
        {
        }

        // ============ 执行入口 ============
        public virtual void Execute()
        {
            if (Context == null) return;

            var target = GetTarget();
            if (target == null || !CanApplyTo(target)) return;

            IsRunning = true;
            var effectData = EffectNodeData;

            if (effectData?.durationType == EffectDurationType.Instant)
            {
                // === 瞬时效果 ===
                ExecuteInitialFlow(target);
                ExecuteCompleteFlow();
                IsRunning = false;
            }
            else
            {
                // === 持续效果 ===
                var existingEffect = target.EffectContainer.FindStackableEffect(this);

                if (existingEffect != null)
                {
                    // 堆叠处理
                    var existingData = existingEffect.EffectNodeData;
                    int stackLimit = existingData?.stackLimit ?? 0;
                    bool isAtStackLimit = stackLimit > 0 && existingEffect.StackCount >= stackLimit;
                    if (isAtStackLimit)
                    {
                        var overflowPolicy = existingData?.stackOverflowPolicy ?? StackOverflowPolicy.DenyApplication;
                        if (overflowPolicy == StackOverflowPolicy.AllowOverflowEffect)
                            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "溢出", GetExecutionContext());
                        if (overflowPolicy == StackOverflowPolicy.DenyApplication)
                        {
                            existingEffect.Refresh();
                            WasRefreshed = true;
                            return;
                        }
                    }
                    existingEffect.AddStack();
                    WasRefreshed = true;
                }
                else
                {
                    // 新效果
                    ExecuteInitialFlow(target);

                    if (effectData?.isPeriodic == true && effectData?.executeOnApplication == true)
                        ExecutePeriodicFlow();

                    if (effectData?.durationType == EffectDurationType.Duration && Duration <= 0)
                    {
                        ExecuteCompleteFlow();
                        IsRunning = false;
                    }
                    else
                    {
                        // 加入Container并应用
                        target.EffectContainer.AddEffect(this);
                        Target = target;
                        IsApplied = true;
                        ActivationTime = UnityEngine.Time.time;

                        if (!Tags.GrantedTags.IsEmpty)
                            Target.OwnedTags.AddTags(Tags.GrantedTags);
                        if (!Tags.RemoveGameplayEffectsWithTags.IsEmpty)
                            Target.RemoveActiveEffectsWithTags(Tags.RemoveGameplayEffectsWithTags);
                        RegisterTagListener();
                        // 持续效果：添加Modifier到属性
                        if (Target.Attributes != null && Modifiers?.Count > 0)
                        {
                            var modContext = CreateCalculationContext(Target);
                            foreach (var modifier in Modifiers)
                            {
                                var attribute = Target.Attributes.GetAttribute(modifier.TargetAttrType);
                                if (attribute != null)
                                {
                                    attribute.AddModifier(modifier, this);
                                    attribute.Recalculate(modContext);
                                }
                            }
                        }
                    }
                }
            }
        }

        // ============ 三大流程（被多处调用） ============

        /// <summary>
        /// 初始流程: 初始Cue → (瞬时:属性修改) → 初始效果 → 初始钩子
        /// 调用处: Execute(瞬时), Execute(持续-新效果)
        /// </summary>
        private void ExecuteInitialFlow(AbilitySystemComponent target)
        {
            var ctx = GetExecutionContext();

            // 瞬时效果：直接修改属性BaseValue
            if (EffectNodeData?.durationType == EffectDurationType.Instant && target?.Attributes != null && Modifiers?.Count > 0)
            {
                var calcContext = CreateCalculationContext(target);
                foreach (var modifier in Modifiers)
                {
                    var attribute = target.Attributes.GetAttribute(modifier.TargetAttrType);
                    if (attribute == null) continue;
                    float magnitude = modifier.CalculateMagnitude(calcContext);
                    switch (modifier.Operation)
                    {
                        case ModifierOperation.Add: attribute.BaseValue += magnitude; break;
                        case ModifierOperation.Multiply: attribute.BaseValue *= magnitude; break;
                        case ModifierOperation.Divide: if (Math.Abs(magnitude) > 0.0001f) attribute.BaseValue /= magnitude; break;
                        case ModifierOperation.Override: attribute.BaseValue = magnitude; break;
                    }
                }
            }

            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "初始效果", ctx);
            OnInitialHook(target);
        }

        /// <summary>
        /// 周期流程: 周期Cue → 每周期执行 → 周期钩子
        /// 调用处: Execute(周期立即执行), Tick(周期触发)
        /// </summary>
        private void ExecutePeriodicFlow()
        {
            var ctx = GetExecutionContext();
            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "每周期执行", ctx);
            OnPeriodicHook();
        }

        /// <summary>
        /// 完成流程: 完成Cue → 完成效果 → 完成钩子
        /// 调用处: Execute(瞬时), Execute(持续-Duration<=0), Remove()
        /// </summary>
        private void ExecuteCompleteFlow()
        {
            var ctx = GetExecutionContext();
            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "完成效果", ctx);
            OnCompleteHook();
        }

        // ============ 三个钩子（子类可重写） ============
        protected virtual void OnInitialHook(AbilitySystemComponent target) { }
        protected virtual void OnPeriodicHook() { }
        protected virtual void OnCompleteHook() { }

        /// <summary>
        /// 获取执行上下文（子类可重写，如Buff提供子上下文）
        /// 基类直接返回传入的上下文，不修改 StackCount
        /// 只有 BuffEffectSpec 等"触发源"才会创建新上下文并设置 StackCount
        /// </summary>
        protected virtual SpecExecutionContext GetExecutionContext()
        {
            return Context;
        }

        // ============ Tick ============
        public virtual void Tick(float deltaTime)
        {
            if (IsExpired || !IsApplied) return;

            ElapsedTime += deltaTime;
            var effectData = EffectNodeData;

            if (effectData?.isPeriodic == true && Period > 0)
            {
                PeriodTimer += deltaTime;
                if (PeriodTimer >= Period)
                {
                    PeriodTimer -= Period;
                    ExecutePeriodicFlow();
                }
            }

            if (effectData?.durationType == EffectDurationType.Duration && Duration > 0 && ElapsedTime >= Duration)
                Expire();
        }

        // ============ 刷新 ============
        public void Refresh()
        {
            var effectData = EffectNodeData;
            if (effectData?.stackDurationRefreshPolicy == StackDurationRefreshPolicy.RefreshOnSuccessfulApplication)
            {
                ElapsedTime = 0f;
                ActivationTime = UnityEngine.Time.time;
            }
            if (effectData?.stackPeriodResetPolicy == StackPeriodResetPolicy.ResetOnSuccessfulApplication)
                PeriodTimer = 0f;

            WasRefreshed = true;
            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "刷新时", GetExecutionContext());
        }

        // ============ 过期和移除 ============
        public void Expire()
        {
            if (IsExpired) return;

            var policy = EffectNodeData?.stackExpirationPolicy ?? StackExpirationPolicy.ClearEntireStack;
            switch (policy)
            {
                case StackExpirationPolicy.ClearEntireStack:
                    IsExpired = true;
                    Remove();
                    break;
                case StackExpirationPolicy.RemoveSingleStackAndRefreshDuration:
                    if (StackCount > 1)
                    {
                        StackCount--;
                        ActivationTime = UnityEngine.Time.time;
                        ElapsedTime = 0f;
                        RecalculateModifiers();
                    }
                    else
                    {
                        IsExpired = true;
                        Remove();
                    }
                    break;
                case StackExpirationPolicy.RefreshDuration:
                    if (StackCount > 0)
                    {
                        ActivationTime = UnityEngine.Time.time;
                        ElapsedTime = 0f;
                    }
                    else
                    {
                        IsExpired = true;
                        Remove();
                    }
                    break;
            }
        }

        public void Remove()
        {
            // 取消Cue
            if (_triggeredCueSpecs != null)
            {
                foreach (var cue in _triggeredCueSpecs)
                    if (cue != null && cue.IsRunning) cue.Cancel();
                _triggeredCueSpecs.Clear();
            }

            // 移除属性修改器
            if (Target?.Attributes != null)
            {
                foreach (var modifier in Modifiers)
                {
                    var attribute = Target.Attributes.GetAttribute(modifier.TargetAttrType);
                    if (attribute != null)
                    {
                        attribute.RemoveModifiersFromSource(this);
                        attribute.Recalculate();
                    }
                }
            }

            // 移除标签
            if (Target != null && !Tags.GrantedTags.IsEmpty)
                Target.OwnedTags.RemoveTags(Tags.GrantedTags);
            UnregisterTagListener();
            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "全部移除后", GetExecutionContext());
            ExecuteCompleteFlow();

            IsExpired = true;
            IsRunning = false;
        }

        public virtual void Cancel()
        {
            if (!IsRunning && !IsApplied) return;

            IsCancelled = true;
            IsRunning = false;

            if (_triggeredCueSpecs != null)
            {
                foreach (var cue in _triggeredCueSpecs)
                    if (cue != null && cue.IsRunning) cue.Cancel();
                _triggeredCueSpecs.Clear();
            }

            if (Target?.Attributes != null)
            {
                foreach (var modifier in Modifiers)
                {
                    var attribute = Target.Attributes.GetAttribute(modifier.TargetAttrType);
                    if (attribute != null)
                    {
                        attribute.RemoveModifiersFromSource(this);
                        attribute.Recalculate();
                    }
                }
            }

            if (Target != null && !Tags.GrantedTags.IsEmpty)
                Target.OwnedTags.RemoveTags(Tags.GrantedTags);

            SpecExecutor.ExecuteConnectedNodes(SkillId, NodeGuid, "全部移除后", GetExecutionContext());

            IsExpired = true;
        }

        // ============ 堆叠 ============
        public bool AddStack(int count = 1)
        {
            var effectData = EffectNodeData;
            int stackLimit = effectData?.stackLimit ?? 0;
            var overflowPolicy = effectData?.stackOverflowPolicy ?? StackOverflowPolicy.DenyApplication;

            if (stackLimit > 0 && StackCount >= stackLimit && overflowPolicy == StackOverflowPolicy.DenyApplication)
            {
                Refresh();
                return false;
            }

            int newStack = stackLimit > 0 ? Math.Min(StackCount + count, stackLimit) : StackCount + count;
            if (newStack == StackCount) return false;

            StackCount = newStack;
            Refresh();
            RecalculateModifiers();
            return true;
        }

        public bool RemoveStack(int count = 1)
        {
            int newStack = Math.Max(0, StackCount - count);
            if (newStack == StackCount) return false;

            StackCount = newStack;
            if (newStack == 0) Expire();
            else RecalculateModifiers();
            return true;
        }

        private void RecalculateModifiers()
        {
            if (Target?.Attributes == null) return;

            // 重新计算属性（属性计算时会从 Source 获取 StackCount）
            foreach (var modifier in Modifiers)
            {
                var attribute = Target.Attributes.GetAttribute(modifier.TargetAttrType);
                attribute?.MarkDirty();
                attribute?.Recalculate();
            }
        }

        /// <summary>
        /// 注册标签变化监听
        /// </summary>
        private void RegisterTagListener()
        {
            if (Target?.OwnedTags == null) return;

            // 只有配置了 OngoingBlockedTags 才需要监听
            if (!Tags.OngoingRequiredTags.IsEmpty)
            {
                Target.OwnedTags.OnTagAdded += OnOwnerTagAdded;
            }
        }

        /// <summary>
        /// 取消标签变化监听
        /// </summary>
        private void UnregisterTagListener()
        {
            if (Target?.OwnedTags == null) return;

            if (!Tags.OngoingRequiredTags.IsEmpty)
            {
                Target.OwnedTags.OnTagAdded -= OnOwnerTagAdded;
            }
        }
        /// <summary>
        /// 拥有者标签添加时的回调
        /// </summary>
        private void OnOwnerTagAdded(GameplayTag tag)
        {
            // 检查是否是 OngoingBlockedTags 中的标签
            if (Tags.OngoingRequiredTags.HasTag(tag))
            {
                // 获得了阻止标签，取消技能
                Remove();
            }
        }

        // ============ Cue管理 ============
        internal void RegisterTriggeredCue(GameplayCueSpec cueSpec)
        {
            if (cueSpec != null && !_triggeredCueSpecs.Contains(cueSpec))
                _triggeredCueSpecs.Add(cueSpec);
        }

        // ============ 辅助方法 ============
        protected AbilitySystemComponent GetTarget()
        {
            var nodeData = NodeData;
            return nodeData == null ? Context?.MainTarget : Context?.GetTarget(nodeData.targetType);
        }

        public bool CanApplyTo(AbilitySystemComponent target)
        {
            if (target == null) return false;
            if (!Tags.ApplicationRequiredTags.IsEmpty && !target.HasAllTags(Tags.ApplicationRequiredTags)) return false;
            if (!Tags.ApplicationImmunityTags.IsEmpty && target.HasAnyTags(Tags.ApplicationImmunityTags)) return false;
            return true;
        }

        public ModifierCalculationContext CreateCalculationContext(AbilitySystemComponent target)
        {
            return new ModifierCalculationContext
            {
                SourceAttributes = Source?.Attributes,
                TargetAttributes = target?.Attributes,
                SnapshotValues = SnapshotValues,
                EffectLevel = Level
            };
        }

        public void SetSetByCallerValue(string key, float value) => SetByCallerValues[key] = value;
        public float GetSetByCallerValue(string key, float defaultValue = 0f) =>
            SetByCallerValues.TryGetValue(key, out float value) ? value : defaultValue;

        public virtual void Reset()
        {
            IsRunning = false;
            IsCancelled = false;
            IsApplied = false;
            IsExpired = false;
            WasRefreshed = false;
            ElapsedTime = 0f;
            PeriodTimer = 0f;
            StackCount = 1;
            Modifiers?.Clear();
            SetByCallerValues?.Clear();
            SnapshotValues?.Clear();
            _triggeredCueSpecs?.Clear();
        }
    }
}

using System;
using System.Collections.Generic;
using SkillEditor.Data;

namespace SkillEditor.Runtime
{
    /// <summary>
    /// 技能容器 - 管理ASC拥有的所有技能
    /// </summary>
    public class AbilityContainer
    {
        /// <summary>
        /// 所属的ASC
        /// </summary>
        private readonly AbilitySystemComponent _owner;

        /// <summary>
        /// 已授予的技能列表
        /// </summary>
        private readonly List<GameplayAbilitySpec> _grantedAbilities = new List<GameplayAbilitySpec>();

        /// <summary>
        /// 正在激活的技能列表
        /// </summary>
        private readonly List<GameplayAbilitySpec> _activeAbilities = new List<GameplayAbilitySpec>();

        /// <summary>
        /// 待移除的技能（避免遍历时修改）
        /// </summary>
        private readonly List<GameplayAbilitySpec> _pendingRemove = new List<GameplayAbilitySpec>();

        /// <summary>
        /// 是否正在更新
        /// </summary>
        private bool _isUpdating;

        /// <summary>
        /// 已授予技能数量
        /// </summary>
        public int GrantedCount => _grantedAbilities.Count;

        /// <summary>
        /// 激活中技能数量
        /// </summary>
        public int ActiveCount => _activeAbilities.Count;

        // ============ 事件 ============

        /// <summary>
        /// 技能授予事件
        /// </summary>
        public event Action<GameplayAbilitySpec> OnAbilityGranted;

        /// <summary>
        /// 技能移除事件
        /// </summary>
        public event Action<GameplayAbilitySpec> OnAbilityRemoved;

        // ============ 构造函数 ============

        public AbilityContainer(AbilitySystemComponent owner)
        {
            _owner = owner;
        }

        // ============ 技能管理 ============

        /// <summary>
        /// 授予技能
        /// </summary>
        public GameplayAbilitySpec GrantAbility(SkillGraphData graphData)
        {
            if (graphData == null)
                return null;

            var spec = new GameplayAbilitySpec(graphData, _owner);
            _grantedAbilities.Add(spec);

            OnAbilityGranted?.Invoke(spec);
            return spec;
        }

        /// <summary>
        /// 授予技能并设置技能ID
        /// </summary>
        public GameplayAbilitySpec GrantAbility(SkillGraphData graphData, int skillId)
        {
            var spec = GrantAbility(graphData);
            if (spec?.AbilityNodeData != null)
            {
                spec.AbilityNodeData.skillId = skillId;
            }
            return spec;
        }

        /// <summary>
        /// 移除技能
        /// </summary>
        public bool RemoveAbility(GameplayAbilitySpec spec)
        {
            if (spec == null || !_grantedAbilities.Contains(spec))
                return false;

            // 如果技能正在激活，先取消
            if (spec.IsActive)
            {
                spec.Cancel();
                _activeAbilities.Remove(spec);
            }

            _grantedAbilities.Remove(spec);
            OnAbilityRemoved?.Invoke(spec);
            return true;
        }

        /// <summary>
        /// 尝试激活技能
        /// </summary>
        public bool TryActivateAbility(GameplayAbilitySpec spec, AbilitySystemComponent target = null)
        {
            if (spec == null || !_grantedAbilities.Contains(spec))
                return false;

            // 检查是否被其他技能阻止
            if (IsAbilityBlocked(spec))
                return false;

            if (spec.Activate(target))
            {
                _activeAbilities.Add(spec);
                return true;
            }

            return false;
        }

        /// <summary>
        /// 检查技能是否被阻止
        /// </summary>
        private bool IsAbilityBlocked(GameplayAbilitySpec spec)
        {
            if (spec.Tags.AssetTags.IsEmpty)
                return false;

            foreach (var activeAbility in _activeAbilities)
            {
                if (activeAbility.BlocksAbilityWithTags(spec.Tags.AssetTags))
                    return true;
            }

            return false;
        }

        /// <summary>
        /// 取消技能
        /// </summary>
        public void CancelAbility(GameplayAbilitySpec spec)
        {
            if (spec == null || !spec.IsActive)
                return;

            spec.Cancel();

            if (_isUpdating)
            {
                _pendingRemove.Add(spec);
            }
            else
            {
                _activeAbilities.Remove(spec);
            }
        }

        /// <summary>
        /// 结束技能
        /// </summary>
        public void EndAbility(GameplayAbilitySpec spec, bool wasCancelled = false)
        {
            if (spec == null || !spec.IsActive)
                return;

            spec.End(wasCancelled);

            if (_isUpdating)
            {
                _pendingRemove.Add(spec);
            }
            else
            {
                _activeAbilities.Remove(spec);
            }
        }

        /// <summary>
        /// 取消带有指定标签的所有技能
        /// </summary>
        public int CancelAbilitiesWithTags(GameplayTagSet tags)
        {
            if (tags.IsEmpty)
                return 0;

            int cancelledCount = 0;
            for (int i = _activeAbilities.Count - 1; i >= 0; i--)
            {
                var ability = _activeAbilities[i];
                if (ability.Tags.AssetTags.HasAnyTags(tags))
                {
                    CancelAbility(ability);
                    cancelledCount++;
                }
            }

            return cancelledCount;
        }

        /// <summary>
        /// 取消所有激活的技能
        /// </summary>
        public void CancelAllAbilities()
        {
            for (int i = _activeAbilities.Count - 1; i >= 0; i--)
            {
                CancelAbility(_activeAbilities[i]);
            }
        }

        // ============ 查询方法 ============

        /// <summary>
        /// 获取所有已授予的技能
        /// </summary>
        public IReadOnlyList<GameplayAbilitySpec> GetGrantedAbilities()
        {
            return _grantedAbilities;
        }

        /// <summary>
        /// 获取所有激活中的技能
        /// </summary>
        public IReadOnlyList<GameplayAbilitySpec> GetActiveAbilities()
        {
            return _activeAbilities;
        }

        /// <summary>
        /// 根据图表数据查找技能
        /// </summary>
        public GameplayAbilitySpec FindAbilityByGraphData(SkillGraphData graphData)
        {
            foreach (var spec in _grantedAbilities)
            {
                if (spec.GraphData == graphData)
                    return spec;
            }
            return null;
        }


        /// <summary>
        /// 根据技能ID查找技能
        /// </summary>
        public GameplayAbilitySpec FindAbilityById(int skillId)
        {
            foreach (var spec in _grantedAbilities)
            {
                if (spec.AbilityNodeData?.skillId == skillId)
                    return spec;
            }
            return null;
        }

        /// <summary>
        /// 检查是否拥有带指定标签的技能
        /// </summary>
        public bool HasAbilityWithTag(GameplayTag tag)
        {
            foreach (var spec in _grantedAbilities)
            {
                if (spec.Tags.AssetTags.HasTag(tag))
                    return true;
            }
            return false;
        }

        /// <summary>
        /// 检查是否有激活中的带指定标签的技能
        /// </summary>
        public bool HasActiveAbilityWithTag(GameplayTag tag)
        {
            foreach (var spec in _activeAbilities)
            {
                if (spec.Tags.AssetTags.HasTag(tag))
                    return true;
            }
            return false;
        }

        // ============ 更新 ============

        /// <summary>
        /// 每帧更新
        /// </summary>
        public void Tick(float deltaTime)
        {
            _isUpdating = true;

            for (int i = 0; i < _activeAbilities.Count; i++)
            {
                var ability = _activeAbilities[i];
                ability.Tick(deltaTime);

                // 检查技能是否已结束
                if (!ability.IsActive && !_pendingRemove.Contains(ability))
                {
                    _pendingRemove.Add(ability);
                }
            }

            _isUpdating = false;

            // 处理待移除的技能
            if (_pendingRemove.Count > 0)
            {
                foreach (var ability in _pendingRemove)
                {
                    _activeAbilities.Remove(ability);
                }
                _pendingRemove.Clear();
            }
        }

        /// <summary>
        /// 清空所有技能
        /// </summary>
        public void Clear()
        {
            CancelAllAbilities();
            _grantedAbilities.Clear();
            _activeAbilities.Clear();
            _pendingRemove.Clear();
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace SkillEditor.Data
{
    /// <summary>
    /// 游戏标签容器 - 可变的标签集合（带引用计数）
    /// 用于运行时动态添加/移除标签
    /// </summary>
    [Serializable]
    public class GameplayTagContainer
    {
        [SerializeField] private List<GameplayTag> _tags = new List<GameplayTag>();

        /// <summary>
        /// 标签引用计数
        /// </summary>
        private Dictionary<int, int> _tagCounts = new Dictionary<int, int>();

        /// <summary>
        /// 标签变化事件（通用）
        /// </summary>
        public event Action OnTagsChanged;

        /// <summary>
        /// 标签首次添加事件（计数 0→1 时触发）
        /// </summary>
        public event Action<GameplayTag> OnTagAdded;

        /// <summary>
        /// 标签完全移除事件（计数 1→0 时触发）
        /// </summary>
        public event Action<GameplayTag> OnTagRemoved;

        /// <summary>
        /// 标签计数变化事件（可选，用于 UI 显示层数等）
        /// </summary>
        public event Action<GameplayTag, int, int> OnTagCountChanged;

        /// <summary>
        /// 标签列表（只读）
        /// </summary>
        public IReadOnlyList<GameplayTag> Tags => _tags;

        /// <summary>
        /// 标签数量
        /// </summary>
        public int Count => _tags.Count;

        /// <summary>
        /// 是否为空
        /// </summary>
        public bool IsEmpty => _tags.Count == 0;

        /// <summary>
        /// 获取标签的引用计数
        /// </summary>
        public int GetTagCount(GameplayTag tag)
        {
            if (!tag.IsValid) return 0;
            return _tagCounts.TryGetValue(tag.GetHashCode(), out int count) ? count : 0;
        }

        /// <summary>
        /// 添加标签（带引用计数）
        /// </summary>
        public void AddTag(GameplayTag tag)
        {
            if (!tag.IsValid) return;

            int hashCode = tag.GetHashCode();
            int oldCount = _tagCounts.TryGetValue(hashCode, out int c) ? c : 0;
            int newCount = oldCount + 1;
            _tagCounts[hashCode] = newCount;

            if (oldCount == 0)
            {
                // 首次添加，加入列表
                _tags.Add(tag);
                OnTagAdded?.Invoke(tag);
            }

            OnTagCountChanged?.Invoke(tag, oldCount, newCount);
            OnTagsChanged?.Invoke();
        }

        /// <summary>
        /// 添加多个标签
        /// </summary>
        public void AddTags(GameplayTagSet tagSet)
        {
            if (tagSet.IsEmpty) return;

            for (int i = 0; i < tagSet.Count; i++)
            {
                AddTag(tagSet[i]);
            }
        }

        /// <summary>
        /// 移除标签（带引用计数）
        /// </summary>
        public bool RemoveTag(GameplayTag tag)
        {
            if (!tag.IsValid) return false;

            int hashCode = tag.GetHashCode();
            if (!_tagCounts.TryGetValue(hashCode, out int oldCount) || oldCount <= 0)
                return false;

            int newCount = oldCount - 1;

            if (newCount <= 0)
            {
                // 完全移除
                _tagCounts.Remove(hashCode);
                for (int i = _tags.Count - 1; i >= 0; i--)
                {
                    if (_tags[i] == tag)
                    {
                        _tags.RemoveAt(i);
                        break;
                    }
                }
                OnTagRemoved?.Invoke(tag);
            }
            else
            {
                _tagCounts[hashCode] = newCount;
            }

            OnTagCountChanged?.Invoke(tag, oldCount, newCount);
            OnTagsChanged?.Invoke();
            return true;
        }

        /// <summary>
        /// 移除多个标签
        /// </summary>
        public void RemoveTags(GameplayTagSet tagSet)
        {
            if (tagSet.IsEmpty) return;

            for (int i = 0; i < tagSet.Count; i++)
            {
                RemoveTag(tagSet[i]);
            }
        }

        /// <summary>
        /// 清空所有标签
        /// </summary>
        public void Clear()
        {
            if (_tags.Count > 0)
            {
                // 触发所有标签的移除事件
                foreach (var tag in _tags)
                {
                    OnTagRemoved?.Invoke(tag);
                }
                _tags.Clear();
                _tagCounts.Clear();
                OnTagsChanged?.Invoke();
            }
        }

        /// <summary>
        /// 检查是否包含指定标签（支持层级匹配）
        /// </summary>
        public bool HasTag(GameplayTag tag)
        {
            if (!tag.IsValid || IsEmpty) return false;

            for (int i = 0; i < _tags.Count; i++)
            {
                if (_tags[i].HasTag(tag))
                    return true;
            }
            return false;
        }

        /// <summary>
        /// 检查是否包含指定标签（精确匹配）
        /// </summary>
        public bool HasTagExact(GameplayTag tag)
        {
            if (!tag.IsValid || IsEmpty) return false;

            for (int i = 0; i < _tags.Count; i++)
            {
                if (_tags[i] == tag)
                    return true;
            }
            return false;
        }

        /// <summary>
        /// 检查是否包含所有指定标签
        /// </summary>
        public bool HasAllTags(GameplayTagSet other)
        {
            if (other.IsEmpty) return true;
            if (IsEmpty) return false;

            for (int i = 0; i < other.Count; i++)
            {
                if (!HasTag(other[i]))
                    return false;
            }
            return true;
        }

        /// <summary>
        /// 检查是否包含任意一个指定标签
        /// </summary>
        public bool HasAnyTags(GameplayTagSet other)
        {
            if (other.IsEmpty || IsEmpty) return false;

            for (int i = 0; i < other.Count; i++)
            {
                if (HasTag(other[i]))
                    return true;
            }
            return false;
        }

        /// <summary>
        /// 检查是否不包含任何指定标签
        /// </summary>
        public bool HasNoneTags(GameplayTagSet other)
        {
            return !HasAnyTags(other);
        }

        /// <summary>
        /// 转换为不可变的 GameplayTagSet
        /// </summary>
        public GameplayTagSet ToTagSet()
        {
            return new GameplayTagSet(_tags);
        }

        /// <summary>
        /// 从 GameplayTagSet 设置标签
        /// </summary>
        public void SetFromTagSet(GameplayTagSet tagSet)
        {
            Clear();
            if (!tagSet.IsEmpty)
            {
                foreach (var tag in tagSet.Tags)
                {
                    AddTag(tag);
                }
            }
        }

        public override string ToString()
        {
            if (IsEmpty) return "[]";
            return "[" + string.Join(", ", _tags.ConvertAll(t => t.ToString())) + "]";
        }
    }
