        #region 属性修改器配置 UI

        private void CreateModifiersUI()
        {
            var container = CreateConfigContainer("属性修改器");

            var headerContainer = new VisualElement
            {
                style =
                {
                    flexDirection = FlexDirection.Row,
                    justifyContent = Justify.SpaceBetween,
